// Regenerates supabase/seed.sql from src/data/cases.js:  npm run seed:sql
// The generated file is idempotent (insert ... on conflict do update), so it can be
// pasted into the Supabase SQL editor any number of times.
const fs = require("fs");
const path = require("path");
const { seedRows } = require("../src/data/cases");

const COLUMNS = {
  seasons: ["id", "number", "title", "language", "unlocked"],
  cases: ["id", "season_id", "number", "title", "description", "objective", "difficulty", "xp_reward", "prerequisite_case_id", "stages", "concept", "lesson", "resolution"],
  challenges: ["id", "case_id", "language", "starter_code", "hint", "hints"],
  challenge_tests: ["id", "challenge_id", "name", "stdin", "expected_output", "hidden"],
  evidence: ["id", "case_id", "code", "text", "condition"],
};
const JSONB = new Set(["stages", "lesson", "resolution", "hints"]);

function literal(column, value) {
  if (value === null || value === undefined) return "null";
  if (JSONB.has(column)) return `$cd$${JSON.stringify(value)}$cd$::jsonb`;
  if (typeof value === "boolean" || typeof value === "number") return String(value);
  const s = String(value);
  if (s.includes("$cd$")) throw new Error(`Value for ${column} contains the reserved quote tag $cd$`);
  return `$cd$${s}$cd$`;
}

const rows = seedRows();
let sql = "-- GENERATED by scripts/generate-seed-sql.js from src/data/cases.js — do not edit by hand.\n";
sql += "-- Run after schema.sql. Safe to run repeatedly: existing rows are updated in place.\n\n";
for (const [table, cols] of Object.entries(COLUMNS)) {
  if (!rows[table].length) continue;
  const values = rows[table].map((r) => `  (${cols.map((c) => literal(c, r[c])).join(", ")})`).join(",\n");
  const updates = cols.filter((c) => c !== "id").map((c) => `${c} = excluded.${c}`).join(", ");
  sql += `insert into ${table} (${cols.join(", ")}) values\n${values}\non conflict (id) do update set ${updates};\n\n`;
}
const out = path.join(__dirname, "../supabase/seed.sql");
fs.writeFileSync(out, sql);
console.log(`Wrote ${path.relative(process.cwd(), out)} (${Object.values(rows).reduce((n, r) => n + r.length, 0)} rows).`);
